var i=`0154-lavangi-chicken`;var t=`world-0154`;var a=`AZ`;var o=`western-asia`;var l=4;var s=91;var r={en:`Lavangi Chicken`,ua:`Курка лявянгі`};var g={en:`A classic dish from Azerbaijan, featuring walnut, yellow onion, whole chicken, pomegranate arils. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Азербайджан. Основні складники: волоський горіх, жовта цибуля, ціла курка, зерна граната. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`walnut`,230,`g`],[`yellow-onion`,220,`g`],[`pomegranate-molasses`,90,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:12,i:[[`whole-chicken`,1300,`g`]]},{en:`Roast in a preheated 190°C oven for about 65 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 65 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:65,i:[[`unsalted-butter`,60,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`pomegranate-arils`,90,`g`]]}];var d={slug:i,id:t,country:`AZ`,region:o,servings:4,minutes:91,title:r,text:g,steps:u};export{a as country,d as default,t as id,s as minutes,o as region,l as servings,i as slug,u as steps,g as text,r as title};